            Ok(DocumentSocketAdmissionV1 {
                socket: DocumentSocketGrantReceiptV1 {
                    schema: "semio.hub.document-socket-grant/v1".into(),
                    protocol: "semio.session.v1".into(),
                    actor_id: format!("hub.v1.{}", "3".repeat(64)),
