    assert_witness::<SeverityMutation>(include_str!("../../🧫️fixtures/🧬️mutations/🚦️severity/🧬️mutations/🚫️set-error-n/🧫️fixtures/🧾️wire-witness/🦠️mutation/🔣️.json"));
