    assert_eq!(ledger.iter().map(|entry| entry.edit_id.as_str()).collect::<Vec<_>>(), vec!["first", "last", "replacement"]);
    let removed = ArtifactStoreMessageLedgerRetirement::new(removed.edit_id, removed.messages);
