    let root_children: Vec<&HistoryColumn> = columns.iter().filter(|column| column.parent_checkpoint_id.as_deref() == Some(root.as_str())).collect();
    assert_eq!(root_children.len(), 3, "root forked three ways: a1, b1, main-resumed");
}

